import java.io.InputStream;
import java.io.IOException;
import java.util.Arrays;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int head = 0;
        private int tail = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private byte read() {
            if (head >= tail) {
                head = 0;
                try {
                    tail = in.read(buffer, 0, buffer.length);
                } catch (IOException e) {
                    tail = -1;
                }
                if (tail <= 0) return -1;
            }
            return buffer[head++];
        }

        public int nextInt() {
            byte c = read();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = read();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + c - '0';
                c = read();
            }
            return res;
        }
    }

    static class Edge implements Comparable<Edge> {
        int u, v, w;

        Edge(int u, int v, int w) {
            this.u = u;
            this.v = v;
            this.w = w;
        }

        @Override
        public int compareTo(Edge o) {
            return Integer.compare(o.w, this.w);
        }
    }

    static int[] parentDSU;

    static int find(int i) {
        if (parentDSU[i] == i)
            return i;
        return parentDSU[i] = find(parentDSU[i]);
    }

    static boolean union(int i, int j) {
        int rootI = find(i);
        int rootJ = find(j);
        if (rootI != rootJ) {
            parentDSU[rootI] = rootJ;
            return true;
        }
        return false;
    }

    static int[] head;
    static int[] to;
    static int[] next;
    static int[] weight;
    static int edgeCount = 0;

    static void addEdge(int u, int v, int w) {
        to[edgeCount] = v;
        weight[edgeCount] = w;
        next[edgeCount] = head[u];
        head[u] = edgeCount++;
    }

    static final int LOGN = 18;
    static int[][] up;
    static int[][] minWeight;
    static int[] depth;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        int N = scanner.nextInt();
        if (N <= 0) return;
        int B = scanner.nextInt();

        Edge[] edges = new Edge[B];
        for (int i = 0; i < B; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            int w = scanner.nextInt();
            edges[i] = new Edge(u, v, w);
        }

        Arrays.sort(edges);

        parentDSU = new int[N + 1];
        for (int i = 1; i <= N; i++) {
            parentDSU[i] = i;
        }

        head = new int[N + 1];
        Arrays.fill(head, -1);
        to = new int[2 * N];
        next = new int[2 * N];
        weight = new int[2 * N];

        int edgesAdded = 0;
        for (int i = 0; i < B; i++) {
            if (union(edges[i].u, edges[i].v)) {
                addEdge(edges[i].u, edges[i].v, edges[i].w);
                addEdge(edges[i].v, edges[i].u, edges[i].w);
                edgesAdded++;
                if (edgesAdded == N - 1) break;
            }
        }

        up = new int[LOGN][N + 1];
        minWeight = new int[LOGN][N + 1];
        depth = new int[N + 1];

        // BFS to set up depth, up[0], minWeight[0]
        int[] queue = new int[N + 1];
        boolean[] visited = new boolean[N + 1];
        int qHead = 0, qTail = 0;

        queue[qTail++] = 1;
        visited[1] = true;
        depth[1] = 0;
        up[0][1] = 1;
        minWeight[0][1] = Integer.MAX_VALUE;

        while (qHead < qTail) {
            int u = queue[qHead++];
            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                int w = weight[e];
                if (!visited[v]) {
                    visited[v] = true;
                    depth[v] = depth[u] + 1;
                    up[0][v] = u;
                    minWeight[0][v] = w;
                    queue[qTail++] = v;
                }
            }
        }

        for (int j = 1; j < LOGN; j++) {
            for (int i = 1; i <= N; i++) {
                int anc = up[j - 1][i];
                up[j][i] = up[j - 1][anc];
                minWeight[j][i] = Math.min(minWeight[j - 1][i], minWeight[j - 1][anc]);
            }
        }

        int C = scanner.nextInt();
        StringBuilder sb = new StringBuilder();

        for (int k = 0; k < C; k++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            sb.append(query(u, v)).append('\n');
        }

        System.out.print(sb.toString());
    }

    static int query(int u, int v) {
        int ans = Integer.MAX_VALUE;

        if (depth[u] < depth[v]) {
            int temp = u;
            u = v;
            v = temp;
        }

        for (int j = LOGN - 1; j >= 0; j--) {
            if (depth[u] - (1 << j) >= depth[v]) {
                ans = Math.min(ans, minWeight[j][u]);
                u = up[j][u];
            }
        }

        if (u == v) return ans;

        for (int j = LOGN - 1; j >= 0; j--) {
            if (up[j][u] != up[j][v]) {
                ans = Math.min(ans, Math.min(minWeight[j][u], minWeight[j][v]));
                u = up[j][u];
                v = up[j][v];
            }
        }

        ans = Math.min(ans, Math.min(minWeight[0][u], minWeight[0][v]));
        return ans;
    }
}
